begin;
set local statement_timeout='30s';
do $test$
declare owner_v uuid:=gen_random_uuid();family_v uuid:=gen_random_uuid();service_v uuid;order_v uuid;cancel_v uuid;staff_v uuid;name_v text;
 device_v text:=repeat('c',43);login_v text:=repeat('d',43);before_v jsonb;after_v jsonb;audit_v jsonb;wa_v jsonb;ledger_count bigint;points_count bigint;order_count bigint;
begin
 insert into auth.users(id,aud,role) values(owner_v,'authenticated','authenticated');
 insert into public.laundry_owner_accounts(auth_user_id,is_active) values(owner_v,true);
 perform set_config('request.jwt.claim.sub',owner_v::text,true);
 update public.laundry_pos_outlets set active=true,write_enabled=true,finance_enabled=true,pilot_test_only=true,package_workflow_enabled=true;
 perform public.laundry_pos_save_package('REGULAR',(select revision from public.laundry_pos_duration_packages where code='REGULAR'),'Reguler',4320,true);
 perform public.laundry_pos_save_family(family_v,0,'{"name":"QA V31 receipt","category":"QA V31","unit":"kg","position":1,"active":true}',
  '[{"code":"REGULAR","price_idr":"6000","active":true},{"code":"EXPRESS","price_idr":"0","active":false},{"code":"FLASH","price_idr":"0","active":false}]');
 select id into service_v from public.laundry_services where family_id=family_v and duration_package_code='REGULAR';
 order_v:=(public.laundry_pos_owner_create_order(gen_random_uuid(),'UJI - V31 snapshot',null,
  jsonb_build_array(jsonb_build_object('service_id',service_v,'quantity','2.375','revision',1)),null,null)->>'order_id')::uuid;
 perform public.laundry_pos_v3_finance('PAYMENT',gen_random_uuid(),order_v,'2500','CASH',1);
 before_v:=public.laundry_pos_v31_print_receipt(order_v);
 if before_v->>'status'<>'PARTIAL' or before_v->>'remaining'<>'11750' or before_v->>'order_version'<>'2' or before_v->>'payment_version'<>'1' or before_v->>'snapshot_at' is null then raise exception 'DP snapshot incomplete';end if;
 if before_v->>'actor'<>'Owner MasJawa' or before_v->'items'->0->>'quantity_milli'<>'2375' then raise exception 'creator or quantity incorrect';end if;
 staff_v:=public.laundry_pos_owner_save_cashier(null,'QA V31 Receiver','{"order_view":true,"payment_collect":true}',true);
 select username into name_v from public.laundry_pos_staff where staff_id=staff_v;
 perform set_config('request.jwt.claim.sub','',true);
 if not public.laundry_pos_cashier_direct_id_login(name_v,device_v,login_v) then raise exception 'cashier login failed';end if;
 audit_v:=public.laundry_pos_order_audit(order_v,device_v,login_v);
 if audit_v->'payments'->0->>'internal_reference' is null or audit_v->'payments'->0->>'cash_ledger_id' is null then raise exception 'audit links missing';end if;
 begin perform public.laundry_pos_v31_print_receipt(order_v,device_v,login_v);raise exception 'print without grant accepted';exception when insufficient_privilege then null;end;
 begin perform public.laundry_pos_print_receipt(order_v,device_v,login_v);raise exception 'legacy print without grant accepted';exception when insufficient_privilege then null;end;
 begin perform public.laundry_pos_v31_whatsapp_receipt(order_v,'NEW',device_v,login_v);raise exception 'WhatsApp without grant accepted';exception when insufficient_privilege then null;end;
 perform public.laundry_pos_v3_finance('PAYMENT',gen_random_uuid(),order_v,'11750','QRIS',2,null,null,device_v,login_v);
 perform set_config('request.jwt.claim.sub',owner_v::text,true);
 after_v:=public.laundry_pos_v31_print_receipt(order_v);wa_v:=public.laundry_pos_v31_whatsapp_receipt(order_v,'NEW');audit_v:=public.laundry_pos_order_audit(order_v);
 if after_v->>'payment_version'=before_v->>'payment_version' or after_v->>'order_version'=before_v->>'order_version' or after_v->>'status'<>'PAID' or after_v->>'remaining'<>'0' then raise exception 'snapshot did not change after payment';end if;
 if after_v->'payments'->1->>'receiver'<>'QA V31 Receiver' or after_v->'payments'->1->>'method'<>'QRIS' or after_v->>'actor'<>'Owner MasJawa' then raise exception 'creator and receiver confused';end if;
 if after_v->'payments'->0 ? 'internal_reference' or after_v->'payments'->0 ? 'payment_id' or after_v->'payments'->0 ? 'cash_ledger_id' then raise exception 'customer data leaked internal references';end if;
 if (after_v-'snapshot_at'-'contact_draft')<>(wa_v-'snapshot_at'-'contact_draft') then raise exception 'customer receipt snapshots differ';end if;
 select count(*) into ledger_count from public.laundry_pos_cash_ledger;select count(*) into points_count from public.laundry_pos_point_links;select count(*) into order_count from public.laundry_pos_orders;
 perform public.laundry_pos_v31_print_receipt(order_v);perform public.laundry_pos_v31_print_receipt(order_v);perform public.laundry_pos_v31_whatsapp_receipt(order_v,'NEW');perform public.laundry_pos_order_audit(order_v);
 if ledger_count<>(select count(*) from public.laundry_pos_cash_ledger) or points_count<>(select count(*) from public.laundry_pos_point_links) or order_count<>(select count(*) from public.laundry_pos_orders) then raise exception 'read surface mutated transaction';end if;
 perform public.laundry_pos_owner_work_status(gen_random_uuid(),order_v,'READY');
 perform public.laundry_pos_owner_work_status(gen_random_uuid(),order_v,'COLLECTED');
 after_v:=public.laundry_pos_v31_print_receipt(order_v);
 if after_v->>'work_status'<>'COLLECTED' or after_v->>'status'<>'PAID' or after_v->>'collected_at' is null then raise exception 'paid collection history missing';end if;
 perform public.laundry_pos_v3_finance('FULL_REFUND',gen_random_uuid(),order_v,null,null,(after_v->>'order_version')::bigint,'QA V31 full refund after collection');
 after_v:=public.laundry_pos_v31_print_receipt(order_v);
 if after_v->>'status'<>'REFUNDED' or after_v->>'remaining'<>'0' or after_v->>'paid'<>'14250' or after_v->>'refunded'<>'14250' or jsonb_array_length(after_v->'refunds')<>2 then raise exception 'refund history or zero debt incorrect';end if;
 wa_v:=public.laundry_pos_v31_whatsapp_receipt(order_v,'NEW');audit_v:=public.laundry_pos_order_audit(order_v);
 if after_v->>'work_status'<>'COLLECTED' or after_v->>'collected_at' is null or wa_v->>'status'<>'REFUNDED' or audit_v->>'status'<>'REFUNDED' then raise exception 'collected refund history not readable';end if;
 if audit_v->>'remaining'<>'0' or wa_v->>'remaining'<>'0' then raise exception 'V31 audit or WhatsApp refund created debt';end if;
 if (public.laundry_pos_print_receipt(order_v))->>'remaining'<>'14250' or (public.laundry_pos_whatsapp_receipt(order_v,'NEW'))->>'remaining'<>'14250' then raise exception 'legacy refund accounting balance changed';end if;
 begin perform public.laundry_pos_v31_whatsapp_receipt(order_v,'COLLECTED');raise exception 'refunded handover draft accepted';exception when raise_exception then if sqlerrm<>'receipt_status_invalid' then raise;end if;end;
 cancel_v:=(public.laundry_pos_owner_create_order(gen_random_uuid(),'UJI - V31 cancel',null,jsonb_build_array(jsonb_build_object('service_id',service_v,'quantity','0.75','revision',1)),null,null)->>'order_id')::uuid;
 perform public.laundry_pos_owner_cancel_order(gen_random_uuid(),cancel_v,'QA V31 cancellation',1);
 after_v:=public.laundry_pos_v31_print_receipt(cancel_v);
 if after_v->>'status'<>'CANCELLED' or after_v->>'work_status'<>'CANCELLED' or after_v->>'remaining'<>'0' then raise exception 'cancelled receipt not readable or has debt';end if;
 if (public.laundry_pos_print_receipt(cancel_v))->>'remaining'<>'4500' or (public.laundry_pos_whatsapp_receipt(cancel_v,'NEW'))->>'remaining'<>'4500' then raise exception 'legacy cancelled accounting balance changed';end if;
 if (public.laundry_pos_v31_whatsapp_receipt(cancel_v,'NEW'))->>'remaining'<>'0' or (public.laundry_pos_order_audit(cancel_v))->>'remaining'<>'0' then raise exception 'V31 cancelled balance changed';end if;
 if after_v->'point_simulation'->>'state'<>'CANCELLED' then raise exception 'cancelled simulation history missing';end if;
 perform set_config('request.jwt.claim.sub','',true);
 execute 'set local role anon';
 begin perform public.laundry_pos_order_audit(order_v);raise exception 'anonymous audit accepted';exception when insufficient_privilege then null;end;
 begin perform public.laundry_pos_v31_print_receipt(order_v);raise exception 'anonymous print accepted';exception when insufficient_privilege then null;end;
 execute 'reset role';
end;$test$;
rollback;
